from dataclasses import dataclass
from typing import TypeAlias


UserId: TypeAlias = str


@dataclass
class Entity:
    id: str

    def identity(self) -> str:
        return self.id


@dataclass
class User(Entity):
    name: str
    email: str
    active: bool = True

    def display_name(self) -> str:
        label: str = self.name.strip()
        return label or self.email


@dataclass
class Admin(User):
    permissions: list[str] = None

    def can_access(self, resource: str) -> bool:
        permissions = self.permissions or []
        return resource in permissions


class ServiceError(Exception):
    pass


class UserNotFound(ServiceError):
    pass

from .models import User


class Repository:
    def __init__(self):
        self._items: dict[str, User] = {}

    def get(self, key: str) -> User | None:
        return self._items.get(key)

    def save(self, user: User) -> None:
        self._items[user.id] = user


class UserRepository(Repository):
    def active_users(self) -> list[User]:
        return [user for user in self._items.values() if user.active]


class CachedUserRepository(UserRepository):
    def get(self, key: str) -> User | None:
        result: User | None = super().get(key)
        return result

from .models import User as UserModel, UserNotFound
from .repository import UserRepository

# File-local aliases retain their declaration and assignment history.
Account = UserModel
Member = Account


class BaseService:
    def __init__(self, repository: UserRepository):
        self.repository = repository


class UserService(BaseService):
    """Application operations for user accounts."""

    def find_user(self, user_id: str) -> UserModel:
        user: UserModel = self.repository.get(user_id)
        if user is None:
            raise UserNotFound(user_id)
        return user

    def update_email(self, user_id: str, email: str) -> UserModel:
        user: UserModel = self.find_user(user_id)
        normalized: str = email.strip().lower()
        previous: str = user.email

        if normalized == previous:
            return user

        user.email = normalized
        self.repository.save(user)
        return user

    def create_member(self, name: str, email: str) -> Member:
        member: Member = Member(id=email, name=name, email=email)
        self.repository.save(member)
        return member


class AuditedUserService(UserService):
    def update_email(self, user_id: str, email: str) -> UserModel:
        result: UserModel = super().update_email(user_id, email)
        return result
